mapper.select:
SELECT followee_id AS user_id, created_at AS followed_at
FROM follow
WHERE follower_id = #{ownerId}
ORDER BY created_at DESC, followee_id DESC
LIMIT #{size}

SELECT follower_id AS user_id, created_at AS followed_at
FROM follow
WHERE followee_id = #{ownerId}
ORDER BY created_at DESC, follower_id DESC
LIMIT #{size}

SELECT f.followee_id AS user_id, p.display_name, f.created_at AS followed_at
FROM follow f
JOIN user_profile p ON p.user_id = f.followee_id
WHERE f.follower_id = #{userId}

    AND (f.created_at < #{beforeTime}
        OR (f.created_at = #{beforeTime} AND f.followee_id < #{beforeId}))

ORDER BY f.created_at DESC, f.followee_id DESC
LIMIT #{pageSize}

SELECT f.follower_id AS user_id, p.display_name, f.created_at AS followed_at
FROM follow f
JOIN user_profile p ON p.user_id = f.follower_id
WHERE f.followee_id = #{userId}

    AND (f.created_at < #{beforeTime}
        OR (f.created_at = #{beforeTime} AND f.follower_id < #{beforeId}))

ORDER BY f.created_at DESC, f.follower_id DESC
LIMIT #{pageSize}
